// scripts/lib/published-title.ts
var metadata = /^(?:가사|해석|번역|발음|독음|듣기|MV|PV|노래|공식|한국어)(?:[ /|,]+(?:가사|해석|번역|발음|독음|듣기|MV|PV|노래|공식|한국어))*$/i;
function cleanPublishedTitle(value) {
  let text = value.normalize("NFKC").replace(/^[\s/「『“"']+|[\s」』”"']+$/g, "").trim();
  if (/라는\s*노래|그대로\s*출력|출력\s*[:：]|번역하지\s*마|한국어\s*표기\s*없/.test(text)) return null;
  if (text.startsWith("(")) {
    let depth = 0, end = -1;
    for (let i = 0; i < text.length; i++) {
      if (text[i] === "(") depth++;
      if (text[i] === ")" && --depth === 0) {
        end = i;
        break;
      }
    }
    if (end < 0) return null;
    text = text.slice(1, end).trim();
    if (text.includes(":")) text = text.split(":").at(-1).trim();
    if (text.includes(",")) {
      const pieces = text.split(",").map((s) => s.trim()).filter((s) => /[가-힣]/.test(s));
      if (pieces.length) text = pieces.at(-1);
    }
  } else {
    if (text.startsWith(")")) return null;
    text = text.split(/\s*[/|]\s*/)[0].trim();
    text = text.replace(/\s*\((?:\d{6,}|가사|해석|번역|발음|독음|듣기|MV|PV)[^)]*\).*$/i, "").trim();
    text = text.replace(/\s+(?:가사|해석|번역|발음|독음|듣기|MV|PV|뮤직비디오|라는 노래|콘셉트|비하인드|M\/V).*$/i, "").trim();
  }
  if (!/[가-힣]/.test(text) || /[\p{Script=Han}\p{Script=Hiragana}\p{Script=Katakana}\p{Emoji_Presentation}]/u.test(text) || metadata.test(text) || text.length > 70 || /^(?:라는 노래|이 름|제 목|가 수)|(?:\[|\])/.test(text)) return null;
  return text;
}

